-- 車いすマスタ.カラム情報に連携コード1, 連携コード2を追加
UPDATE sys_master_define
SET column_info = '{"fields": [{"type": "number", "alias": "code", "title": "車いすコード", "physical_name": "wheel_chair_cd"}, {"type": "string", "alias": "name", "title": "車いす名称", "format": null, "hidden": "false", "locked": "true", "editable": "true", "validation": {"max": null, "min": null, "required": "true", "maxlength": 250}, "physical_name": "wheel_chair_name"}, {"type": "modal", "title": "詳細"}, {"type": "number", "alias": null, "title": "重量(kg)", "format": null, "hidden": "false", "editable": "true", "validation": {"max": 300, "min": 0, "required": null, "maxlength": null}, "physical_name": "wheel_chair_weight"}, {"type": "combo1", "title": "個人所有フラグ", "validation": {"required": false}, "physical_name": "is_personal"}, {"type": "combo1", "alias": null, "title": "所有患者", "format": null, "hidden": "false", "editable": "false", "validation": {"max": null, "min": null, "required": null, "maxlength": null}, "physical_name": "pat_id"}, {"type": "date", "alias": null, "title": "重量校正日", "format": null, "hidden": "false", "editable": "false", "validation": {"max": null, "min": null, "required": null, "maxlength": null}, "physical_name": "scale_date"}, {"type": "combo1", "alias": null, "title": "重量校正者", "format": null, "hidden": "false", "editable": "false", "validation": {"max": null, "min": null, "required": null, "maxlength": null}, "physical_name": "scale_user_id"}, {"type": "string", "alias": null, "title": "連携コード1", "format": null, "hidden": "false", "locked": "false", "editable": "true", "validation": {"max": null, "min": null, "required": "false", "maxlength": "20"}, "physical_name": "in_hospital_cd_1"}, {"type": "string", "alias": null, "title": "連携コード2", "format": null, "hidden": "false", "locked": "false", "editable": "true", "validation": {"max": null, "min": null, "required": "false", "maxlength": "20"}, "physical_name": "in_hospital_cd_2"}, {"type": "del", "title": "削除", "physical_name": "is_del"}, {"type": "disp", "title": "削除", "physical_name": "is_disp"}]}',
    up_date = CURRENT_TIMESTAMP
WHERE master_physical_name = 'mst_wheel_chair';
